//! Test-only helpers around the `tiny` fixture grammar in `tests/fixtures/grammars/tiny`.
//!
//! The fixture's `parser.c` was generated by the tree-sitter CLI from the
//! `grammar.js` beside it. Tests compile it into a shared library on demand so
//! the dynamic loader and query extractor are exercised against a real grammar
//! that is *not* linked into the binary.

use std::path::{Path, PathBuf};
use std::process::Command;

pub const TINY_GRAMMAR_NAME: &str = "tiny";

pub fn tiny_grammar_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/grammars/tiny")
}

/// Compile the fixture grammar into `<out_dir>/tiny.so`.
///
/// Returns `None` after printing why when no C compiler is on PATH, so the
/// caller can skip; a compiler that is present but fails is a hard error.
pub fn compile_tiny_grammar(out_dir: &Path) -> Option<PathBuf> {
    let src = tiny_grammar_dir().join("src");
    let out = out_dir.join(format!("{TINY_GRAMMAR_NAME}.so"));

    let result = Command::new("cc")
        .args(["-shared", "-fPIC", "-O0", "-I"])
        .arg(&src)
        .arg("-o")
        .arg(&out)
        .arg(src.join("parser.c"))
        .output();

    match result {
        Ok(output) if output.status.success() => Some(out),
        Ok(output) => panic!(
            "cc failed to compile the fixture grammar ({}):\n{}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        ),
        Err(e) => {
            eprintln!("skipping: no C compiler available to build the fixture grammar ({e})");
            None
        }
    }
}
